/**
 * Novus OS - semantic design tokens (Novus Fluent).
 *
 * Generated by tools/themegen/themegen.py from theme.toml - do not edit.
 * Roles are resolved at paint time from the current light/dark
 * palette, so the shell, the window manager and the installer all
 * change together instead of each keeping a copy of the colours.
 */

#ifndef NOVUS_ND_THEME_H
#define NOVUS_ND_THEME_H

#include "uefi.h"

#define ND_THEME_TOKEN_VERSION 0x00010000u

typedef enum {
  ND_THEME_LIGHT = 0,
  ND_THEME_DARK = 1,
  ND_THEME_AUTO = 2
} nd_theme_mode_t;

typedef struct {
  UINT32 canvas_top;
  UINT32 canvas_bottom;
  UINT32 surface;
  UINT32 card;
  UINT32 subtle;
  UINT32 stroke;
  UINT32 text;
  UINT32 dim;
  UINT32 accent;
  UINT32 on_accent;
  UINT32 success;
  UINT32 warn;
  UINT32 danger;
  UINT32 selection;
  UINT32 shadow;
} nd_tokens_t;

typedef struct {
  INT32 radius_control;
  INT32 radius_card;
  INT32 radius_pill;
  INT32 space_xs;
  INT32 space_s;
  INT32 space_m;
  INT32 space_l;
  INT32 space_xl;
  INT32 control_h;
  INT32 button_h;
  INT32 row_h;
  INT32 title_h;
  INT32 shadow_spread;
} nd_metrics_t;

/* Current palette (auto already resolved), metrics, and runtime state. */
const nd_tokens_t  *nd_tokens(void);
const nd_metrics_t *nd_metrics(void);
const nd_tokens_t  *nd_tokens_for(int dark);

nd_theme_mode_t nd_theme_mode(void);
int             nd_theme_is_dark(void);
void            nd_theme_set_mode(nd_theme_mode_t mode);
UINT32          nd_theme_version(void);
/* Re-evaluate auto mode (RTC hour). Returns 1 when it changed. */
int             nd_theme_resolve(void);

UINT32 nd_theme_accent(void);
/* Top colour of wallpaper `index` in the current mode, for pickers. */
UINT32 nd_theme_paper_top(UINT32 index);
void   nd_theme_set_accent(UINT32 rgb);
UINT32 nd_theme_wallpaper(void);
void   nd_theme_set_wallpaper(UINT32 index);
int    nd_theme_wallpaper_count(void);

#endif /* NOVUS_ND_THEME_H */
